    // Click the delete/remove button for Apple Juice
    const deleteBtn = page.locator("mat-row, tr").filter({ hasText: "Apple Juice" }).getByRole("button").filter({ hasText: /delete|remove|×|✕/i }).or(
      page.locator("mat-row, tr").filter({ hasText: "Apple Juice" }).locator("button[aria-label*='delete'], button[aria-label*='remove']")
    ).or(
      page.locator("mat-row, tr").filter({ hasText: "Apple Juice" }).locator("button").last()
    ).first();
    await expect(deleteBtn).toBeVisible();
    await deleteBtn.click();

    // After removal: Apple Juice should no longer be visible in the basket
